const read=p=>readFileSync(new URL(p,import.meta.url),'utf8');
const gp=read('fixtures/gp_stack_scope_template_20261014.mjs'),hq=read('fixtures/gp-hq-preservation-successor-20261015.mjs');
const receipt={source:'a'.repeat(40),hq:{source:'a'.repeat(40),gpEnabled:false,partnersEnabled:true,percentage:100,deploymentId:'11111111-1111-1111-1111-111111111111',versionId:'22222222-2222-2222-2222-222222222222',bundleSha256:'b'.repeat(64),otherBindingsSha256:'c'.repeat(64),bundleBytes:123,run:42}};
test('a literal GP bridge preserves every original flags-OFF assertion and inverse',()=>{const next=buildGpActivationBridge(gp);assert.equal(originalGpActivationBridge(next),gp);assert(next.includes("'GP lookup flags must remain OFF'"));assert(next.includes('activation?activation.head:rawCurrent'));assert(next.includes('if(activation)activation.assertCurrent()'));});
test('unknown changed GP source anchors cannot silently adopt a successor',()=>assert.throws(()=>buildGpActivationBridge(gp.replace('const actual=currentHead();try{','const actual=changed();try{')),/exact activation bridge anchor/));
test('raw source freshness and flags-OFF checks cannot be removed in the bridge',()=>{const next=buildGpActivationBridge(gp);assert.throws(()=>originalGpActivationBridge(next.replace('if(activation)activation.assertCurrent();}});','}});')),/exact activation bridge anchor/);assert.notEqual(originalGpActivationBridge(next.replace("'GP lookup flags must remain OFF'","'removed control'")),gp);});
test('caller-supplied private activation contexts are never publicly exported',()=>{const next=buildGpActivationBridge(gp);assert(!next.includes('export function verifyGpCodeStackBeforeDirectoryActivation'));assert(!next.includes('export function gpMemberCodeHistoricalViewBeforeDirectoryActivation'));assert(next.includes('const activation=gpDirectoryActivationHistoricalView();'));});
test('separate HQ activation source retains literal original GP-off predecessor and all assertions',()=>{const next=buildGpActivationHqSource(hq,receipt);assert.equal(originalGpActivationHqSource(next,receipt),hq);assert(next.includes('755cce5e-6308-405f-be59-2e515caa82af'));assert(next.includes('HQ_DIRECTORY_ACTIVATION_START.version'));assert(next.includes("'GP activation remains provably off; opaque/duplicate bindings refused'"));});
test('the actual accepted GP-code provider tuple cannot be replaced after source preparation',()=>{const next=buildGpActivationHqSource(hq,receipt);assert.throws(()=>originalGpActivationHqSource(next,{...receipt,hq:{...receipt.hq,versionId:'33333333-3333-3333-3333-333333333333'}}),/Literal accepted/);});
test('HQ callers change only the exact import and preserve all original statements',()=>{const before=Object.fromEntries(GP_ACTIVATION_HQ_CALLERS.map(p=>[p,read('fixtures/'+p)])),current=Object.fromEntries(GP_ACTIVATION_HQ_CALLERS.map(p=>[p,buildGpActivationHqCaller(p,before[p])]));for(const p of GP_ACTIVATION_HQ_CALLERS)assert.equal(originalGpActivationHqCaller(p,current[p]),before[p]);assert.equal(verifyGpActivationHqSource({current:buildGpActivationHqSource(hq,receipt),original:hq,receipt,currentCallers:current,originalCallers:before}).predecessor.version,receipt.hq.versionId);});
const snap=()=>({deployment:{id:'owned'},version:{id:'v',resources:{bindings:[{name:'HQ_PARTNERS_ENABLED',type:'plain_text',text:'true'},{name:'OTHER_BINDING',type:'secret_text',text:'retained fictional fixture'},{name:'MEMBER_GP_DIRECTORY_V2_ENABLED',type:'plain_text',text:'true'}]}},bundle:Buffer.from('fixture')});
test('the provider adapter passes every existing field unchanged to the old kernel except one approved flag',()=>{const s=snap(),copy={...structuredClone(s),bundle:Buffer.from(s.bundle)},expected={owned:'tuple',otherBindingsSha256:gpActivationBindingsSha256(s.version.resources.bindings)};let called=0;const out=assertActivatedGpHqProviderSnapshot(s,expected,(projected,pins)=>{called++;assert.equal(pins,expected);assert.equal(projected.deployment,s.deployment);assert.equal(projected.bundle,s.bundle);assert.deepEqual(projected.version,{id:'v',resources:{bindings:s.version.resources.bindings.slice(0,2)}});return{gpEnabled:false,partnersEnabled:true,version:'v'};});assert.equal(called,1);assert.equal(out.gpEnabled,true);assert.deepEqual(s,copy);});
for(const scenario of ['absent','false','opaque','duplicate'])test('an unproven true V2 binding fails before the old provider kernel: '+scenario,()=>{const s=snap();if(scenario==='absent')s.version.resources.bindings.pop();if(scenario==='false')s.version.resources.bindings.at(-1).text='false';if(scenario==='opaque')s.version.resources.bindings.at(-1).type='secret_text';if(scenario==='duplicate')s.version.resources.bindings.push({...s.version.resources.bindings.at(-1)});let called=0;assert.throws(()=>assertActivatedGpHqProviderSnapshot(s,{},()=>{called++;}));assert.equal(called,0);});
test('the adapter cannot suppress original whole-bundle, version or partner rejection',()=>assert.throws(()=>assertActivatedGpHqProviderSnapshot(snap(),{otherBindingsSha256:gpActivationBindingsSha256(snap().version.resources.bindings)},()=>{throw Error('original whole-bundle proof failed');}),/original whole-bundle proof failed/));
test('an unrelated provider binding change fails before the retained kernel or any live claim',()=>{const s=snap(),expected={otherBindingsSha256:gpActivationBindingsSha256(s.version.resources.bindings)};assert.equal(assertActivatedGpProviderBindings(s.version,expected).otherBindingsPreserved,true);s.version.resources.bindings[1].text='changed';let calls=0;assert.throws(()=>assertActivatedGpHqProviderSnapshot(s,expected,()=>{calls++;}),/Every other HQ provider binding/);assert.equal(calls,0);});
const hqProof=read('fixtures/gp-hq-preservation-source-20261015.mjs');
test('HQ caller proof wrappers preserve all original assertion bodies and exact inverse',()=>assert.equal(originalGpActivationHqProofSource(buildGpActivationHqProofSource(hqProof)),hqProof));
const fixture=mkdtempSync(join(tmpdir(),'gp-activation-hq-proof-'));mkdirSync(join(fixture,'release'));
writeFileSync(join(fixture,'release/gp-hq-preservation-source-20261015.mjs'),buildGpActivationHqProofSource(hqProof));
for(const file of['gp-directory-activation-hq-source-20261015.mjs','gp-directory-activation-contract-20261015.mjs'])writeFileSync(join(fixture,'release',file),read(file));
writeFileSync(join(fixture,'release/gp-directory-activation-20261015.mjs'),"export function gpDirectoryActivationHistoricalView(){if(globalThis.__gpActivationFixtureError)throw globalThis.__gpActivationFixtureError;return globalThis.__gpActivationFixtureView;}\n");
const proof=await import(pathToFileURL(join(fixture,'release/gp-hq-preservation-source-20261015.mjs')));
const callers=Object.fromEntries(GP_ACTIVATION_HQ_CALLERS.map(p=>[p,read('fixtures/'+p)]));
const setView=(active=true)=>{let checks=0;globalThis.__gpActivationFixtureError=null;globalThis.__gpActivationFixtureView={head:'g',rawHead:active?'f':'g',content:(r,p)=>{assert.equal(r,'g');return callers[p];},assertCurrent(){checks++;}};return()=>checks;};
test('retained caller round-trip assertions still execute on actual F and literal G arguments',()=>{const checks=setView();for(const p of GP_ACTIVATION_HQ_CALLERS){const g=callers[p],f=buildGpActivationHqCaller(p,g),before=proof.originalGpHqCallerSource(p,g);assert.equal(proof.originalGpHqCallerSource(p,f),before);assert.equal(proof.buildGpHqCallerSource(p,before),f);assert.throws(()=>proof.originalGpHqCallerSource(p,f+'\nvoid 0;\n'),/Every original HQ caller assertion/);}assert(checks()>=24);});
test('without an activation, the retained HQ caller proof remains its original G behaviour',()=>{setView(false);for(const p of GP_ACTIVATION_HQ_CALLERS){const before=proof.originalGpHqCallerSource(p,callers[p]);assert.equal(proof.buildGpHqCallerSource(p,before),callers[p]);}});
test('the outer HQ caller proof rejects before original bodies when activation admission fails',()=>{globalThis.__gpActivationFixtureError=Error('actual flag source rejected');assert.throws(()=>proof.originalGpHqCallerSource('hq-management-deploy.mjs',callers['hq-management-deploy.mjs']),/actual flag source rejected/);assert.throws(()=>proof.buildGpHqCallerSource('hq-management-deploy.mjs','invented'),/actual flag source rejected/);globalThis.__gpActivationFixtureError=null;});
test('the preparation CLI refuses unknown actual G and absent terminal receipts before any output',()=>{assert.throws(()=>prepareGpDirectoryActivation({}),/Required explicit --repo/);assert.throws(()=>prepareGpDirectoryActivation({repo:fixture,'accepted-base':'unknown','accepted-tree':'a'.repeat(40),'core-terminal':'absent','hq-terminal':'absent','serving-receipt':'absent','serving-sha256':'b'.repeat(64)}));});
function priorRefFixture({dropFourth=false}={}){
 const root=mkdtempSync(join(tmpdir(),'gp-activation-native-prior-ref-')),release=join(root,'release'),git=(...args)=>execFileSync('/usr/bin/git',['--no-replace-objects','-C',root,...args],{encoding:'utf8',stdio:['ignore','pipe','pipe']}),commit=message=>{git('add','--all');git('-c','user.name=Fictional activation boundary fixture','-c','user.email=fixture@invalid','commit','--quiet','-m',message);return git('rev-parse','HEAD').trim();};mkdirSync(release);git('init','--quiet');
 let source=read('gp-directory-activation-template-20261015.mjs').replace('__POLICY__',JSON.stringify({record:{maintenancePaths:[]},expectedStatuses:{}}));
 if(dropFourth){const fixed='authentic:(v,r,p,h=rawHead)=>authentic(v,r,p,h)';assert.equal(source.split(fixed).length,2);source=source.replace(fixed,'authentic:(v,r,p)=>authentic(v,r,p,rawHead)');}
 writeFileSync(join(release,'gp-directory-activation-20261015.mjs'),source);
 for(const name of['gp-directory-activation-contract-20261015.mjs','gp-directory-activation-source-20261015.mjs','gp-directory-activation-hq-source-20261015.mjs'])writeFileSync(join(release,name),read(name));
 // Only the native authenticity boundary is under test here. No activation
 // registration/provider/source admission is synthesised by this fixture.
 writeFileSync(join(release,'immutable-git-facts.mjs'),"export {execFileSync as immutableHistoryExecFileSync} from 'node:child_process';export const withImmutableHistoryVerification=f=>f();export function assertGitTrackedSourceVisible(){}\n");
 writeFileSync(join(release,'approved-runtime-composition.json'),'{}\n');writeFileSync(join(release,'probe.mjs'),'export default "literal prior G fixture";\n');const prior=commit('Fictional prior native source G');writeFileSync(join(release,'probe.mjs'),'export default "different raw F fixture";\n');const current=commit('Fictional later native source F');
 const script=`import assert from 'node:assert/strict';import {execFileSync} from 'node:child_process';import {gpDirectoryActivationHistoricalView,gpActivationAuthenticatedRead} from './release/gp-directory-activation-20261015.mjs';const g=(...a)=>execFileSync('/usr/bin/git',['--no-replace-objects',...a],{encoding:'utf8'}),blob=(r,p)=>g('rev-parse',r+':'+p).trim(),content=(r,p)=>g('show',r+':'+p),prior=${JSON.stringify(prior)},current=${JSON.stringify(current)},v=gpDirectoryActivationHistoricalView();assert.equal(v.rawHead,current);for(const p of['release/probe.mjs','release']){assert.equal(v.authentic(blob(prior,p),'HEAD',p,prior),true,'genuine literal fourth-ref blob');assert.equal(v.authentic(content(prior,p),'HEAD',p,prior),true,'genuine literal fourth-ref content');assert.equal(v.authentic('forged equal prior source','HEAD',p,prior),false);assert.equal(v.authentic(blob(current,p),'HEAD',p,prior),false,'raw F source must not satisfy explicit prior G');assert.equal(v.authentic(blob(prior,p),'HEAD',p),false,'default raw ref must remain F');assert.equal(v.nativeAuthentic(blob(prior,p),prior,p),true);assert.equal(v.nativeAuthentic(blob(current,p),prior,p),false);assert.equal(gpActivationAuthenticatedRead(blob,v)(prior,p),blob(prior,p));assert.throws(()=>gpActivationAuthenticatedRead((r,path)=>r===prior?'forged equal prior source':blob(r,path),v)(prior,p),/Unauthentic supplied source/);}process.stdout.write('PASS native genuine and forged prior-ref boundary');`;
 try{return spawnSync(process.execPath,['--input-type=module','-e',script],{cwd:root,encoding:'utf8'});}finally{rmSync(root,{recursive:true,force:true});}
}
test('defaulted fourth-head forwarding admits genuine prior native blobs/content and rejects wrong-ref/forged values',()=>{const r=priorRefFixture();assert.equal(r.status,0,r.stderr);assert.match(r.stdout,/PASS native genuine and forged prior-ref boundary/);});
test('the same genuine prior-ref boundary rejects the previous three-argument implementation',()=>{const r=priorRefFixture({dropFourth:true});assert.notEqual(r.status,0);assert.match(r.stderr,/genuine literal fourth-ref blob/);});
test('the GP outer wrapper forwards the admitted activation authentic function without dropping its native-head argument',()=>{const bridge=buildGpActivationBridge(gp);assert(bridge.includes('authentic:activation.authentic,nativeAuthentic:activation.nativeAuthentic'));assert.equal(originalGpActivationBridge(bridge),gp);});
test('final binding accepts and preserves the actual G fourth-head fix without pinning an old three-argument GP property',()=>{const before='authentic:(v,r,p)=>authentic(v,r,p,rawHead)',after='authentic:(v,r,p,h=rawHead)=>authentic(v,r,p,h)';assert.equal(gp.split(before).length,2);const actualNextGp=gp.replace(before,after),bridge=buildGpActivationBridge(actualNextGp);assert(bridge.includes(after));assert.equal(originalGpActivationBridge(bridge),actualNextGp);});
test('15-minute freshness applies to actual input binding, never to the immutable timed source gate',()=>{const scope=read('gp-directory-activation-template-20261015.mjs');assert(!scope.includes('Date.now'));assert(!scope.includes('Date.parse'));assert(!scope.includes('validateGpActivationInputs'));assert(read('prepare-gp-directory-activation-20261015.mjs').includes('predecessor=validateGpActivationInputs('));});
test.after(()=>{rmSync(fixture,{recursive:true,force:true});delete globalThis.__gpActivationFixtureView;delete globalThis.__gpActivationFixtureError;});
